cat > /tmp/sub.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const files = execSync("git grep -l disableTooltip -- src", {encoding:"utf8"}).trim().split("\n");
let total = 0; const touched = [];
const tagRe = /<app-(?:fancy-pill|status-pill)\b[^>]*>/g;
for (const f of files) {
  const src = readFileSync(f, "utf8");
  let n = 0;
  const out = src.replace(tagRe, (tag) => tag.replace(/(\[)?\bdisableTooltip\b(\])?/g, (m,a,b) => { n++; return `${a??""}hideHint${b??""}`; }));
  if (n) { writeFileSync(f, out); total += n; touched.push(`${f}:${n}`); }
}
console.log(touched.join("\n"));
console.log("total", total);
EOF
