cat > /tmp/sub2.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const files = execSync("git grep -l disableTooltip -- src", {encoding:"utf8"}).trim().split("\n");
const names = ["<app-fancy-pill", "<app-status-pill"];
let total = 0; const touched = [];
for (const f of files) {
  const src = readFileSync(f, "utf8");
  let out = "", i = 0, n = 0;
  while (i < src.length) {
    const hit = names.map(nm => src.indexOf(nm, i)).filter(x => x >= 0).sort((a,b)=>a-b)[0];
    if (hit === undefined) { out += src.slice(i); break; }
    out += src.slice(i, hit);
    // scan the tag, respecting quoted attribute values
    let j = hit, q = null;
    while (j < src.length) {
      const c = src[j];
      if (q) { if (c === q) q = null; }
      else if (c === '"' || c === "'") q = c;
      else if (c === ">") { j++; break; }
      j++;
    }
    const tag = src.slice(hit, j);
    out += tag.replace(/(\[)?\bdisableTooltip\b(\])?/g, (m,a,b) => { n++; return `${a??""}hideHint${b??""}`; });
    i = j;
  }
  if (n) { writeFileSync(f, out); total += n; touched.push(`${f}:${n}`); }
}
console.log(touched.length + " files"); console.log("total", total);
EOF
node /tmp/sub2.mjs

