cat > /tmp/reads.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";
const files = execSync("git grep -l disableTooltip -- src", {encoding:"utf8"}).trim().split("\n");
const pats = [
  /\bfancyRef\.disableTooltip\b/g,
  /\bpill\.disableTooltip\b/g,
  /\bfancy\(\)\??\.disableTooltip\b/g,
  /\bfirstPill\(\)\??\.disableTooltip\b/g,
];
let total = 0;
for (const f of files) {
  let src = readFileSync(f, "utf8"); let n = 0;
  for (const p of pats) src = src.replace(p, m => { n++; return m.replace("disableTooltip", "hideHint"); });
  if (n) { writeFileSync(f, src); total += n; }
}
console.log("read-site edits:", total);
EOF
